<?php
namespace qqworld_collector\module\cloud_storage; use Exception; class SFTPConnection { private $connection; private $sftp; public function __construct($host, $port=22) { $this->connection = @ssh2_connect($host, $port); if (! $this->connection) { throw new Exception("Could not connect to $host on port $port."); } } public function login($username, $password) { if (! @ssh2_auth_password($this->connection, $username, $password)) throw new Exception("Could not authenticate with username $username and password $password."); $this->sftp = @ssh2_sftp($this->connection); if (! $this->sftp) throw new Exception("Could not initialize SFTP subsystem."); } private function mkdir($remote_file) { $sftp = $this->sftp; $dir = dirname($remote_file); if (!file_exists("ssh2.sftp://$sftp$dir")) { ssh2_sftp_mkdir($sftp, $dir); } } public function uploadFile($local_file, $remote_file) { if (!preg_match('/^\//i', $remote_file)) $remote_file = '/' . $remote_file; $this->mkdir($remote_file); $sftp = $this->sftp; $stream = @fopen("ssh2.sftp://$sftp$remote_file", 'w'); if (! $stream) throw new Exception("Could not open file: $remote_file"); $data_to_send = @file_get_contents($local_file); if ($data_to_send === false) throw new Exception("Could not open local file: $local_file."); if (@fwrite($stream, $data_to_send) === false) throw new Exception("Could not send data from file: $local_file."); @fclose($stream); } public function receiveFile($remote_file, $local_file) { if (!preg_match('/^\//i', $remote_file)) $remote_file = '/' . $remote_file; $sftp = $this->sftp; $stream = @fopen("ssh2.sftp://$sftp$remote_file", 'r'); if (! $stream) throw new Exception("Could not open file: $remote_file"); $contents = fread($stream, filesize("ssh2.sftp://$sftp$remote_file")); file_put_contents($local_file, $contents); @fclose($stream); } public function getFileSize($remote_file) { if (!preg_match('/^\//i', $remote_file)) $remote_file = '/' . $remote_file; $sftp = $this->sftp; return filesize("ssh2.sftp://$sftp$remote_file"); } public function deleteFile($remote_file){ if (!preg_match('/^\//i', $remote_file)) $remote_file = '/' . $remote_file; $sftp = $this->sftp; $result = unlink("ssh2.sftp://$sftp$remote_file"); if (!$result) { throw new Exception("Could not delete remote file: $remote_file."); } } public function fileExists($remote_file) { if (!preg_match('/^\//i', $remote_file)) $remote_file = '/' . $remote_file; $sftp = $this->sftp; return file_exists("ssh2.sftp://$sftp$remote_file"); } public function scanFilesystem($dir) { $sftp = $this->sftp; $dir = "ssh2.sftp://$sftp/$dir"; $tempArray = array(); $handle = opendir($dir); while (false !== ($file = readdir($handle))) { if (substr("$file", 0, 1) != "."){ if(is_dir($file)) { $tempArray[$file]=scanFilesystem("$dir/$file"); } else { $tempArray[]=$file; } } } closedir($handle); return $tempArray; } }